const icon = (name, label = '') => `<svg class="fd-icon"${label ? ` role="img" aria-label="${label}"` : ' aria-hidden="true"'}><use href="#${name}"></use></svg>`;
const stack = (content) => `<div class="preview-stack">${content}</div>`;

window.FOUNDRY_COMPONENTS = [
  { group: 'Foundation', id: 'grid-breakpoints', name: 'Grid & Breakpoints', description: 'Documents the audited 12-column layout, exact gutters, gaps, card columns, and responsive transitions.', preview: `<div class="fd-layout-audit"><div class="fd-grid-demo" aria-label="Twelve column grid">${Array.from({ length: 12 }, (_, index) => `<span>${index + 1}</span>`).join('')}</div><div class="fd-metric-grid"><article><strong>1440</strong><span>36 px page gutter</span><span>36 px column gap</span></article><article><strong>3-up</strong><span>403 px content cards</span><span>406 px simple cards</span></article><article><strong>2-up</strong><span>659 px feature cards</span><span>36 px gap</span></article><article><strong>≤ 768</strong><span>16 px page gutter</span><span>274 px carousel cards</span></article></div></div>`, accessibility: ['Keep source order meaningful when columns collapse.', 'Do not encode relationships through position alone.', 'Allow horizontal card strips to scroll with keyboard and touch.'] },
  { group: 'Foundation', id: 'component-states', name: 'Component States', description: 'A complete applicable-state matrix for actions, fields, selection controls, navigation, cards, and disclosure.', preview: `<div class="fd-state-matrix"><section><h3>Actions</h3><div class="fd-state-row"><span>Default</span><button class="fd-button fd-button--primary">Continue</button></div><div class="fd-state-row"><span>Hover</span><button class="fd-button fd-button--primary is-hover">Continue</button></div><div class="fd-state-row"><span>Focus</span><button class="fd-button fd-button--primary is-focus">Continue</button></div><div class="fd-state-row"><span>Pressed</span><button class="fd-button fd-button--primary is-active">Continue</button></div><div class="fd-state-row"><span>Loading</span><button class="fd-button fd-button--primary is-loading" aria-busy="true"><span class="fd-spinner"></span>Loading…</button></div><div class="fd-state-row"><span>Disabled</span><button class="fd-button fd-button--primary" disabled>Continue</button></div></section><section><h3>Text fields</h3><div class="fd-state-row"><span>Empty</span><input class="fd-input" placeholder="Enter value"></div><div class="fd-state-row"><span>Filled</span><input class="fd-input is-filled" value="6,500 AUD"></div><div class="fd-state-row"><span>Hover</span><input class="fd-input is-hover" value="6,500 AUD"></div><div class="fd-state-row"><span>Focus</span><input class="fd-input is-focus" value="6,500 AUD"></div><div class="fd-state-row"><span>Error</span><input class="fd-input" aria-invalid="true" value="Invalid value"></div><div class="fd-state-row"><span>Read only</span><input class="fd-input" readonly value="Verified value"></div><div class="fd-state-row"><span>Disabled</span><input class="fd-input" disabled value="Unavailable"></div></section><section><h3>Selection</h3><div class="fd-state-row"><span>Unchecked</span><label class="fd-checkbox"><input type="checkbox"><span class="fd-checkbox__control"></span><span>Option</span></label></div><div class="fd-state-row"><span>Checked</span><label class="fd-checkbox"><input type="checkbox" checked><span class="fd-checkbox__control"></span><span>Option</span></label></div><div class="fd-state-row"><span>Focus</span><label class="fd-checkbox is-focus"><input type="checkbox"><span class="fd-checkbox__control"></span><span>Option</span></label></div><div class="fd-state-row"><span>Error</span><label class="fd-checkbox is-error"><input type="checkbox"><span class="fd-checkbox__control"></span><span>Option</span></label></div><div class="fd-state-row"><span>Disabled</span><label class="fd-checkbox"><input type="checkbox" disabled><span class="fd-checkbox__control"></span><span>Option</span></label></div><div class="fd-state-row"><span>Selected</span><label class="fd-radio"><input type="radio" checked><span class="fd-radio__control"></span><span>Choice</span></label></div></section><section><h3>Navigation & disclosure</h3><div class="fd-state-row"><span>Default</span><div class="fd-tabs__list"><button>Overview</button></div></div><div class="fd-state-row"><span>Hover</span><div class="fd-tabs__list"><button class="is-hover">Overview</button></div></div><div class="fd-state-row"><span>Selected</span><div class="fd-tabs__list"><button aria-selected="true">Overview</button></div></div><div class="fd-state-row"><span>Closed</span><details class="fd-details"><summary>Conditions ${icon('plus')}</summary></details></div><div class="fd-state-row"><span>Open</span><details class="fd-details" open><summary>Conditions ${icon('minus')}</summary><div class="fd-details__content">Disclosure content.</div></details></div></section></div>`, accessibility: ['Do not rely on colour alone to communicate a state.', 'Match visual states to native disabled, checked, selected, expanded, invalid, and busy semantics.', 'Keep focus visible at 200% zoom and in high-contrast modes.'] },
  { group: 'Components', id: 'card-variants', name: 'Card Variants', description: 'Pixel-audited simple, standard, feature, editorial, selected, loading, and mobile-carousel card compositions.', preview: `<div class="fd-card-audit"><section><h3>Simple task cards · 3 × 406 px</h3><div class="fd-simple-card-grid"><article class="fd-card fd-simple-card"><h4>Open an account</h4><button class="fd-icon-button" aria-label="Open an account">${icon('arrow-right')}</button></article><article class="fd-card fd-simple-card is-hover"><h4>Compare loans</h4><button class="fd-icon-button" aria-label="Compare loans">${icon('arrow-right')}</button></article><article class="fd-card fd-simple-card is-focus"><h4>Find a branch</h4><button class="fd-icon-button" aria-label="Find a branch">${icon('arrow-right')}</button></article></div></section><section><h3>Standard cards · 3 × 403 px</h3><div class="fd-standard-card-grid"><article class="fd-card fd-product-card"><div class="fd-card__media"></div><div class="fd-card__body"><span class="fd-card__category">Everyday banking</span><h4>Flexible account</h4><p>Simple services for everyday money management.</p><a class="fd-button fd-button--primary" href="#">Explore</a></div></article><article class="fd-card fd-product-card is-selected"><div class="fd-card__media"></div><div class="fd-card__body"><span class="fd-card__category">Selected</span><h4>Digital account</h4><p>Open and manage an account online.</p><a class="fd-button fd-button--primary" href="#">Explore</a></div></article><article class="fd-card fd-product-card is-loading" aria-busy="true"><div class="fd-card__media fd-skeleton"></div><div class="fd-card__body"><div class="fd-skeleton"></div><div class="fd-skeleton"></div><div class="fd-skeleton"></div></div></article></div></section><section><h3>Feature cards · 2 × 659 px</h3><div class="fd-feature-card-grid"><article class="fd-card fd-feature-card"><div class="fd-card__media"></div><div class="fd-card__body"><h4>Plan your next move</h4><p>Compare options with clear rates and conditions.</p><a class="fd-link" href="#">View details ${icon('arrow-right')}</a></div></article><article class="fd-card fd-feature-card"><div class="fd-card__media"></div><div class="fd-card__body"><h4>Build financial confidence</h4><p>Guidance designed around real decisions.</p><a class="fd-link" href="#">View details ${icon('arrow-right')}</a></div></article></div></section></div>`, accessibility: ['Use semantic headings within each card collection.', 'A fully clickable card should expose one unambiguous interactive target.', 'Loading cards must mark their region busy and keep skeletons hidden from assistive technology.'] },
  { group: 'Components', id: 'button', name: 'Buttons', description: 'Triggers an action with primary, secondary, tertiary, danger, loading, and disabled emphasis.', preview: stack(`<button class="fd-button fd-button--primary">Open an account</button><button class="fd-button fd-button--secondary">Learn more</button><button class="fd-button fd-button--tertiary">Calculate ${icon('arrow-right')}</button><button class="fd-button fd-button--primary" disabled>Unavailable</button>`), accessibility: ['Use a button for actions and a link for navigation.', 'Keep labels short, unique, and action-oriented.', 'Use one primary action per page or task surface.'] },
  { group: 'Components', id: 'icon-button', name: 'Icon button', description: 'Compact action for familiar operations such as search, close, edit, or delete.', preview: stack(`<button class="fd-icon-button" aria-label="Search">${icon('search')}</button><button class="fd-icon-button" aria-label="Edit">${icon('edit')}</button><button class="fd-icon-button" aria-label="Delete">${icon('trash')}</button>`), accessibility: ['Every icon-only button requires an accessible name.', 'Use familiar symbols and provide a tooltip when meaning may be unclear.'] },
  { group: 'Components', id: 'link', name: 'Link', description: 'Navigates to another page, resource, or section.', preview: stack(`<a class="fd-link" href="#">View product details ${icon('arrow-right')}</a><a class="fd-link" href="#">Download conditions ${icon('download')}</a>`), accessibility: ['Describe the destination rather than using “click here”.', 'Use an external-link cue when navigation leaves the current service.'] },
  { group: 'Components', id: 'toggle-group', name: 'Toggle group', description: 'Selects one view or mode from a short, visible set.', preview: stack(`<div class="fd-toggle-group" aria-label="Customer type"><button aria-pressed="true">Personal</button><button aria-pressed="false">Business</button><button aria-pressed="false">Corporate</button></div>`), accessibility: ['Expose selected state with aria-pressed.', 'Keep options mutually exclusive and concise.'] },
  { group: 'Components', id: 'numeric-stepper', name: 'Numeric stepper', description: 'Adjusts a numeric value with direct entry and increment controls.', preview: stack(`<button class="fd-icon-button" aria-label="Decrease">${icon('minus')}</button><strong>50,000 AUD</strong><button class="fd-icon-button" aria-label="Increase">${icon('plus')}</button>`), accessibility: ['Name increment and decrement controls.', 'Do not rely on buttons alone; allow keyboard entry where appropriate.'] },

  { group: 'Components', id: 'field', name: 'Form Elements', description: 'Composes a label, description, control, and validation message.', preview: stack(`<label class="fd-field"><span class="fd-label">Monthly income <span class="fd-label__required">*</span></span><span class="fd-description">Enter your verified net income.</span><input class="fd-input" type="text" value="6,500"><span class="fd-description">AUD per month</span></label>`), accessibility: ['Associate every control with a visible label.', 'Keep help text before errors in the reading order.'] },
  { group: 'Components', id: 'input', name: 'Input', description: 'Single-line text, email, number, amount, and formatted data entry.', preview: stack(`<label class="fd-field"><span class="fd-label">Full name</span><input class="fd-input" placeholder="Enter your name"></label><label class="fd-field"><span class="fd-label">Amount</span><span class="fd-input-group"><input class="fd-input" value="50,000"><span>AUD</span></span></label>`), accessibility: ['Use the correct input type and autocomplete value.', 'Do not use placeholder text as the only label.'] },
  { group: 'Components', id: 'phone-input', name: 'Phone input', description: 'Phone number field with a visible country prefix.', preview: stack(`<label class="fd-field"><span class="fd-label">Phone number</span><span class="fd-input-group"><span>+61</span><input class="fd-input" type="tel" placeholder="___ ___ ___" autocomplete="tel-national"></span></label>`), accessibility: ['Use autocomplete="tel" or tel-national.', 'Keep formatting guidance available while typing.'] },
  { group: 'Components', id: 'date-input', name: 'Date input', description: 'Date entry with a calendar affordance and format hint.', preview: stack(`<label class="fd-field"><span class="fd-label">Date observed</span><span class="fd-date-input"><input class="fd-input" placeholder="DD/MM/YYYY"><svg class="fd-icon" aria-hidden="true"><use href="#calendar"></use></svg></span></label>`), accessibility: ['Communicate the expected format in text.', 'Calendar selection must remain keyboard accessible.'] },
  { group: 'Components', id: 'select', name: 'Select', description: 'Chooses one value from a compact list.', preview: stack(`<label class="fd-field"><span class="fd-label">Issue type</span><select class="fd-select"><option>Select an option</option><option>Cards and payments</option><option>Loans</option><option>Digital banking</option></select></label>`), accessibility: ['Use a native select when advanced custom behaviour is unnecessary.', 'Start with a clear prompt option when selection is required.'] },
  { group: 'Components', id: 'textarea', name: 'Textarea', description: 'Multi-line entry with an optional character counter.', preview: stack(`<label class="fd-field" style="width:100%"><span class="fd-label">Describe the issue</span><textarea class="fd-textarea" maxlength="2000"></textarea><span class="fd-description">2,000 characters remaining</span></label>`), accessibility: ['Do not prevent paste.', 'Announce character limits before they block entry.'] },
  { group: 'Components', id: 'checkbox', name: 'Checkbox', description: 'Selects zero or more independent options.', preview: stack(`<label class="fd-checkbox"><input type="checkbox"><span class="fd-checkbox__control"></span><span>Receive product updates</span></label><label class="fd-checkbox"><input type="checkbox" checked><span class="fd-checkbox__control"></span><span>I accept the privacy notice</span></label>`), accessibility: ['Use a fieldset and legend for related checkboxes.', 'Place long legal labels after the control and keep links operable.'] },
  { group: 'Components', id: 'radio', name: 'Radio', description: 'Selects one option from a mutually exclusive group.', preview: stack(`<fieldset style="border:0;padding:0"><legend class="fd-label">Verified monthly income</legend><label class="fd-radio"><input name="income" type="radio" checked><span class="fd-radio__control"></span><span>At least 6,500 AUD</span></label><label class="fd-radio"><input name="income" type="radio"><span class="fd-radio__control"></span><span>4,500–6,499 AUD</span></label></fieldset>`), accessibility: ['Group radios with fieldset and legend.', 'Arrow-key selection should follow native browser behaviour.'] },
  { group: 'Components', id: 'switch', name: 'Switch', description: 'Turns an immediate setting on or off.', preview: stack(`<label class="fd-switch"><input type="checkbox" checked><span class="fd-switch__control"></span><span>Statistical cookies</span></label><label class="fd-switch"><input type="checkbox"><span class="fd-switch__control"></span><span>Functional cookies</span></label>`), accessibility: ['Use a checkbox when the action requires later submission.', 'State labels should describe the setting, not “on” or “off”.'] },
  { group: 'Components', id: 'file-upload', name: 'File upload', description: 'Uploads one or more supporting documents.', preview: stack(`<label class="fd-file-upload"><strong>Upload supporting documents</strong><span class="fd-description">PDF, JPG or PNG · max 10 MB</span><input type="file" accept=".pdf,.jpg,.jpeg,.png"></label>`), accessibility: ['List accepted formats and limits before the input.', 'Announce upload progress and validation results.'] },
  { group: 'Components', id: 'search-field', name: 'Search Field', description: 'Pairs a labelled search input with a submit action.', preview: stack(`<form class="fd-search" role="search"><input class="fd-input" type="search" aria-label="Search the site" placeholder="Search"><button class="fd-button fd-button--primary" aria-label="Submit search">${icon('search')}<span>Search</span></button></form>`), accessibility: ['Use role="search" on the form.', 'Provide a visible label or an accessible name.'] },
  { group: 'Components', id: 'validation', name: 'Validation message', description: 'Explains how to correct an invalid field.', preview: stack(`<label class="fd-field"><span class="fd-label">Email address</span><input class="fd-input" aria-invalid="true" aria-describedby="email-error" value="anna@"><span id="email-error" class="fd-validation">Enter a complete email address.</span></label>`), accessibility: ['Connect the message with aria-describedby.', 'Explain the correction; do not only state that a value is invalid.'] },
  { group: 'Components', id: 'error-summary', name: 'Error summary', description: 'Collects form errors at the top of a failed submission.', preview: stack(`<section class="fd-error-summary" aria-labelledby="error-title"><h3 id="error-title">There is a problem</h3><ul><li><a href="#">Enter your full name</a></li><li><a href="#">Select an issue type</a></li></ul></section>`), accessibility: ['Move focus to the summary after failed submission.', 'Each message should link to the relevant field.'] },

  { group: 'Components', id: 'alert', name: 'Alerts', description: 'Communicates informational, success, warning, or error status.', preview: stack(`<div class="fd-alert fd-alert--info">${icon('info')}<div class="fd-alert__content"><strong>Planned maintenance</strong><span>Digital services may be unavailable from 23:00.</span></div></div><div class="fd-alert fd-alert--success">${icon('check')}<div class="fd-alert__content"><strong>Application saved</strong><span>You can continue later.</span></div></div>`), accessibility: ['Use role="status" for non-urgent updates and role="alert" for urgent errors.', 'Do not communicate severity by colour alone.'] },
  { group: 'Components', id: 'badge', name: 'Labels & Badges', description: 'Compact status or metadata label.', preview: stack(`<span class="fd-badge">In progress</span><span class="fd-badge fd-badge--success">Available</span><span class="fd-badge fd-badge--danger">Action required</span>`), accessibility: ['Keep badge text explicit.', 'Avoid using badges as the only interactive target.'] },
  { group: 'Components', id: 'chip', name: 'Chip', description: 'Highlights a small category, promotion, or applied filter.', preview: stack(`<span class="fd-chip">New</span><span class="fd-chip">Loans</span><span class="fd-chip">Mobile banking</span>`), accessibility: ['Do not encode critical information in a decorative chip alone.'] },
  { group: 'Components', id: 'tag', name: 'Tag', description: 'Represents a removable selection or category.', preview: stack(`<span class="fd-tag">Accounts <button aria-label="Remove Accounts">${icon('close')}</button></span><span class="fd-tag">Cards <button aria-label="Remove Cards">${icon('close')}</button></span>`), accessibility: ['Name the remove action with the tag value.', 'Keep the visible tag text separate from the button label.'] },
  { group: 'Components', id: 'spinner', name: 'Spinner', description: 'Indicates indeterminate loading for a short operation.', preview: stack(`<span class="fd-spinner" role="status" aria-label="Loading"></span><button class="fd-button fd-button--primary fd-button--loading" disabled><span class="fd-spinner"></span>Loading…</button>`), accessibility: ['Provide a text alternative such as Loading.', 'Use progress for operations with a known completion value.'] },
  { group: 'Components', id: 'progress', name: 'Progress', description: 'Shows known completion in a process.', preview: stack(`<div style="width:100%"><div class="fd-progress" role="progressbar" aria-valuenow="68" aria-valuemin="0" aria-valuemax="100"><span style="width:68%"></span></div><p class="fd-description">68% complete</p></div>`), accessibility: ['Expose min, max, and current values.', 'Include a textual state when progress is important.'] },
  { group: 'Components', id: 'skeleton', name: 'Skeleton', description: 'Reserves layout while content is loading.', preview: stack(`<div style="display:grid;gap:.75rem;width:100%"><div class="fd-skeleton" style="height:8rem"></div><div class="fd-skeleton" style="width:65%"></div><div class="fd-skeleton" style="width:90%"></div></div>`), accessibility: ['Hide purely visual skeleton shapes from assistive technology.', 'Announce the loading state on the containing region.'] },
  { group: 'Components', id: 'tooltip', name: 'Tooltip', description: 'Provides a short label or explanation on hover and focus.', preview: stack(`<span class="fd-tooltip-wrap"><button class="fd-icon-button" aria-describedby="tip-help">${icon('info')}</button><span id="tip-help" role="tooltip" class="fd-tooltip">The annual percentage rate includes fees.</span></span>`), accessibility: ['Show the tooltip on keyboard focus as well as hover.', 'Never place essential interactive content inside a tooltip.'] },
  { group: 'Components', id: 'popover', name: 'Popover', description: 'Displays contextual non-modal content near a trigger.', preview: stack(`<div class="fd-popover"><strong>Rate information</strong><p>The displayed APR is calculated from the selected amount and term.</p><a class="fd-link" href="#">Read conditions</a></div>`), accessibility: ['Move focus into interactive popovers when opened.', 'Support Escape and restore focus to the trigger.'] },
  { group: 'Components', id: 'dialog', name: 'Dialog', description: 'Interrupts the flow for a focused confirmation or task.', preview: stack(`<button class="fd-button fd-button--primary" data-demo-dialog>Open dialog</button><dialog class="fd-dialog"><h2>Continue application?</h2><p>Your current calculation will be saved.</p><div class="fd-dialog__actions"><button class="fd-button fd-button--secondary" data-dialog-close>Cancel</button><button class="fd-button fd-button--primary">Continue</button></div></dialog>`), accessibility: ['Use a clear heading and initial focus target.', 'Trap focus while open and restore it when closed.'] },
  { group: 'Components', id: 'toast', name: 'Toast', description: 'Confirms a lightweight action without blocking work.', preview: stack(`<div class="fd-alert fd-alert--success" role="status">${icon('check')}<div class="fd-alert__content"><strong>Copied</strong><span>The account number is on your clipboard.</span></div></div>`), accessibility: ['Use a polite live region for confirmations.', 'Do not use a toast for information that must be acknowledged.'] },

  { group: 'Components', id: 'card', name: 'Cards', description: 'Groups product or editorial content into a single surface.', preview: stack(`<article class="fd-card fd-card--interactive" style="max-width:24rem"><div class="fd-card__media"></div><div class="fd-card__body"><span class="fd-card__category">Loans</span><h3>Personal loan</h3><p>Apply online and calculate your monthly payment.</p><strong>APR: 9.9%–19.6%</strong><a class="fd-button fd-button--primary" href="#">Calculate</a></div></article>`), accessibility: ['Use one clear interactive target for a fully clickable card.', 'Preserve semantic headings within card collections.'] },
  { group: 'Components', id: 'simple-card', name: 'Simple card', description: 'Compact task or destination card used in help-me-choose grids.', preview: stack(`<article class="fd-card fd-simple-card" style="width:min(100%,32rem)"><span class="fd-wordmark__mark">${icon('card')}</span><h3>Open a bank account</h3><button class="fd-icon-button" aria-label="Open a bank account">${icon('arrow-right')}</button></article>`), accessibility: ['Avoid multiple competing links inside the compact card.', 'Use a heading that describes the destination.'] },
  { group: 'Components', id: 'surface-banner', name: 'Surface banner', description: 'Wide promotional surface with message, art, and call to action.', preview: `<article class="fd-surface-banner" style="width:100%"><div><span class="fd-chip">Mobile banking</span><h2>Everyday banking in one app</h2><p>Manage accounts, cards, payments, and savings wherever you are.</p><button class="fd-button fd-button--primary">Learn more</button></div><div class="fd-surface-banner__art">R</div></article>`, accessibility: ['Keep decorative art out of the accessibility tree.', 'Ensure foreground contrast remains sufficient over imagery.'] },
  { group: 'Components', id: 'table', name: 'Tables', description: 'Displays comparable financial or product data.', preview: `<div class="fd-table-wrap" style="width:100%"><table class="fd-table fd-table--striped"><thead><tr><th>Product</th><th>Interest</th><th>APR</th></tr></thead><tbody><tr><td>Personal loan</td><td>9.49%</td><td>9.9%</td></tr><tr><td>Credit card</td><td>—</td><td>35.1%–37.7%</td></tr></tbody></table></div>`, accessibility: ['Use table headers with correct scope.', 'Provide a caption when the surrounding context is not sufficient.'] },
  { group: 'Components', id: 'divider', name: 'Divider', description: 'Separates adjacent content groups without introducing hierarchy.', preview: stack(`<div style="width:100%"><p>Account information</p><hr class="fd-divider"><p>Contact information</p></div>`), accessibility: ['Use a heading when the separation conveys a new section.', 'Decorative dividers should not add unnecessary announcements.'] },

  { group: 'Components', id: 'breadcrumbs', name: 'Breadcrumbs Utility', description: 'Shows the current page within the site hierarchy.', preview: stack(`<nav aria-label="Breadcrumb"><ol class="fd-breadcrumbs"><li><a class="fd-link" href="#">Home</a>${icon('chevron-right')}</li><li><a class="fd-link" href="#">Loans</a>${icon('chevron-right')}</li><li aria-current="page">Personal loan</li></ol></nav>`), accessibility: ['Wrap the trail in navigation labelled Breadcrumb.', 'Mark the current page with aria-current="page".'] },
  { group: 'Components', id: 'tabs', name: 'Tab & Subnav', description: 'Switches between related content views without page navigation.', preview: `<div class="fd-tabs" style="width:100%"><div class="fd-tabs__list" role="tablist"><button role="tab" aria-selected="true">Overview</button><button role="tab" aria-selected="false">Conditions</button><button role="tab" aria-selected="false">Documents</button></div><div class="fd-tabs__panel" role="tabpanel">Product overview content.</div></div>`, accessibility: ['Implement arrow-key movement within the tab list.', 'Associate each tab with its panel.'] },
  { group: 'Components', id: 'details', name: 'Accordion', description: 'Reveals supporting information on demand.', preview: `<div style="width:100%"><details class="fd-details" open><summary>What documents do I need? ${icon('plus')}</summary><div class="fd-details__content">Identity documents and proof of income may be required.</div></details><details class="fd-details"><summary>How long does it take? ${icon('plus')}</summary><div class="fd-details__content">Timing depends on verification and credit assessment.</div></details></div>`, accessibility: ['Prefer native details and summary for simple disclosure.', 'The summary must describe the hidden content.'] },
  { group: 'Components', id: 'pagination-control', name: 'Pagination Control', description: 'Moves through a long, ordered set of pages.', preview: stack(`<nav class="fd-pagination" aria-label="Pagination"><button aria-label="Previous page">${icon('arrow-left')}</button><button aria-current="page">1</button><button>2</button><button>3</button><button aria-label="Next page">${icon('arrow-right')}</button></nav>`), accessibility: ['Label previous and next controls.', 'Mark the current page with aria-current.'] },
  { group: 'Components', id: 'stepper', name: 'Process stepper', description: 'Shows progress through a multi-step banking flow.', preview: `<ol class="fd-stepper" style="--fd-steps:4;width:100%"><li class="is-complete"><span>${icon('check')}</span><b>Calculate</b></li><li aria-current="step"><span>2</span><b>Details</b></li><li><span>3</span><b>Review</b></li><li><span>4</span><b>Done</b></li></ol>`, accessibility: ['Use an ordered list.', 'Mark the active item with aria-current="step".'] },
  { group: 'Components', id: 'header', name: 'Nav', description: 'Three-level banking navigation: service links, primary product navigation, and online-banking action.', preview: `<header class="fd-header" style="width:100%"><div class="fd-header__service"><b>PERSONAL</b><span>PREMIUM BANKING</span><span>BUSINESS</span><span>Search · Branches · EN</span></div><div class="fd-header__main"><a class="fd-wordmark" href="#"><span class="fd-wordmark__mark">╳</span><span>FOUNDRY UI</span></a><nav class="fd-header__nav"><a href="#">Accounts</a><a href="#">Loans</a><a href="#">Savings</a><a href="#">Digital</a></nav><button class="fd-button fd-button--primary">Online banking</button></div></header>`, accessibility: ['Provide one clear site-home link.', 'Use separate labels for service and primary navigation.'] },
  { group: 'Components', id: 'footer', name: 'Footer', description: 'Multi-column destination map with regulatory and legal metadata.', preview: `<footer class="fd-footer" style="width:100%"><div class="fd-footer__group"><h3>Foundry UI</h3><a href="#">Contact</a><a href="#">Branches and ATMs</a></div><div class="fd-footer__group"><h3>Consumer protection</h3><a href="#">Complaints</a><a href="#">Privacy</a></div><div class="fd-footer__group"><h3>Information</h3><a href="#">Fees and conditions</a><a href="#">Exchange rates</a></div><div class="fd-footer__group"><h3>Products</h3><a href="#">Personal</a><a href="#">Business</a></div><p class="fd-footer__meta">© 2026 · Legal · Sitemap · Imprint</p></footer>`, accessibility: ['Use descriptive headings for link groups.', 'Avoid repeating links already available in the primary navigation unless useful.'] },

  { group: 'Components', id: 'icons', name: 'Icons', description: 'A searchable, dependency-free SVG registry with more than 900 interface, finance, device, transport, and communication symbols.', preview: '', accessibility: ['Decorative icons must use aria-hidden="true".', 'Meaningful standalone icons require an accessible name.', 'Use one icon per button and prefer placement before text.'] },
  { group: 'Foundation', id: 'typography', name: 'Typography', description: 'Portable Hanken Grotesk type scale with native system-font fallbacks.', preview: '', accessibility: ['Preserve heading order independently of visual size.', 'Do not use all caps for long labels or paragraphs.'] },
  { group: 'Foundation', id: 'tokens', name: 'Colors & Tokens', description: 'Portable CSS custom properties for colour, shape, shadow, typography, and control sizing.', preview: '', accessibility: ['Validate colour combinations against WCAG contrast requirements.', 'Do not override focus-ring tokens with invisible styles.'] },
  { group: 'Foundation', id: 'accent-colors', name: 'Accent Colors', description: 'Preset and fully custom accent palettes that propagate through actions, selection, progress, cards, and navigation.', preview: `<div class="fd-accent-playground"><div class="fd-accent-picker"><label for="accent-picker"><strong>Custom accent</strong></label><input id="accent-picker" type="color" value="#2A8288" data-accent-picker><output data-accent-value>#2A8288</output><div class="fd-accent-presets" aria-label="Accent presets"><button class="fd-accent-swatch" style="--swatch:#2A8288" data-accent="#2A8288" aria-label="Teal accent"></button><button class="fd-accent-swatch" style="--swatch:#2563EB" data-accent="#2563EB" aria-label="Blue accent"></button><button class="fd-accent-swatch" style="--swatch:#7C3AED" data-accent="#7C3AED" aria-label="Violet accent"></button><button class="fd-accent-swatch" style="--swatch:#E84A5F" data-accent="#E84A5F" aria-label="Coral accent"></button><button class="fd-accent-swatch" style="--swatch:#16835F" data-accent="#16835F" aria-label="Green accent"></button></div></div><div class="fd-accent-demo" style="--fd-accent:#2A8288;--fd-accent-hover:#236F74;--fd-accent-contrast:#FFFFFF;--fd-accent-soft:#92CFAE;--fd-accent-soft-contrast:#173F42"><button class="fd-button fd-button--primary">Primary action</button><label class="fd-checkbox"><input type="checkbox" checked><span class="fd-checkbox__control"></span><span>Selected option</span></label><div class="fd-progress" style="width:12rem" role="progressbar" aria-valuenow="65"><span style="width:65%;background:var(--fd-accent)"></span></div></div></div>`, accessibility: ['Set both accent contrast tokens to colours that meet text contrast requirements.', 'Treat semantic status colours separately from the brand accent.', 'Pair colour with text, iconography, or position.'] },

  { group: 'Components', id: 'lists', name: 'Lists', description: 'Ordered, unordered, and action-oriented collections with consistent rhythm.', preview: stack(`<div><h3>Required documents</h3><ul class="fd-list"><li>Identity document</li><li>Proof of address</li><li>Income statement</li></ul></div><ol class="fd-list fd-list--ordered"><li>Choose a product</li><li>Enter your details</li><li>Review and submit</li></ol>`), accessibility: ['Use semantic list elements whenever order or grouping matters.', 'Do not simulate lists with visual bullets alone.'] },
  { group: 'Components', id: 'heading-styles', name: 'Heading Styles', description: 'Semantic heading styles from display level through compact module titles.', preview: stack(`<div><h1 class="fd-heading fd-heading--display">Display heading</h1><h2 class="fd-heading fd-heading--1">Page heading</h2><h3 class="fd-heading fd-heading--2">Section heading</h3><h4 class="fd-heading fd-heading--3">Module heading</h4></div>`), accessibility: ['Choose heading elements for document structure, then apply visual styles.', 'Do not skip levels when nesting sections.'] },
  { group: 'Components', id: 'sections-tiles', name: 'Sections & Tiles', description: 'Layout primitives for page regions, dashboards, and compact destination tiles.', preview: `<section class="fd-section" style="width:100%"><header class="fd-section__header"><div><span class="fd-chip">Explore</span><h2>What would you like to do?</h2></div></header><div class="fd-tile-grid"><a class="fd-tile" href="#">Open an account ${icon('arrow-right')}</a><a class="fd-tile" href="#">Compare products ${icon('arrow-right')}</a><a class="fd-tile" href="#">Get support ${icon('arrow-right')}</a></div></section>`, accessibility: ['Give sections descriptive headings.', 'Use links for destination tiles and buttons for actions.'] },
  { group: 'Components', id: 'overlay-marker', name: 'Overlay & Marker', description: 'Text overlays and positional markers for media, maps, and highlighted content.', preview: `<div class="fd-overlay-demo"><div class="fd-overlay"><span class="fd-chip">Featured</span><h3>Build momentum</h3><p>A readable overlay keeps text clear over visual content.</p></div><button class="fd-marker" aria-label="Branch location">${icon('location')}</button></div>`, accessibility: ['Maintain contrast regardless of the underlying image.', 'Give interactive markers a useful accessible name.'] },
  { group: 'Components', id: 'dotnav-slidenav', name: 'Dotnav & Slidenav', description: 'Compact carousel position indicators and previous or next controls.', preview: stack(`<button class="fd-slidenav" aria-label="Previous slide">${icon('arrow-left')}</button><nav class="fd-dotnav" aria-label="Slides"><button aria-label="Slide 1" aria-current="true"></button><button aria-label="Slide 2"></button><button aria-label="Slide 3"></button></nav><button class="fd-slidenav" aria-label="Next slide">${icon('arrow-right')}</button>`), accessibility: ['Name every control and expose the current slide.', 'Pause automatic rotation when the user interacts.'] },
  { group: 'Components', id: 'text-utilities', name: 'Text Utilities', description: 'Small composable classes for alignment, weight, tone, wrapping, and truncation.', preview: stack(`<div style="width:100%"><p class="fd-text-lead">Lead text introduces a section.</p><p class="fd-text-muted">Muted supporting information.</p><p class="fd-text-uppercase">Uppercase metadata</p><p class="fd-text-truncate">A very long single-line value that demonstrates truncation when available space is limited.</p></div>`), accessibility: ['Utilities must not replace semantic elements.', 'Avoid uppercase treatment for sentences and long labels.'] },
  { group: 'Components', id: 'utility-classes', name: 'Utility Classes', description: 'A restrained set of layout, spacing, visibility, and alignment helpers.', preview: stack(`<div class="fd-u-flex fd-u-gap-3 fd-u-items-center fd-u-p-4 fd-u-surface"><span class="fd-badge">Flexible</span><strong class="fd-u-grow">Reusable layout</strong><button class="fd-button fd-button--primary fd-button--small">Action</button></div>`), accessibility: ['Do not use visually hidden utilities on focusable controls.', 'Prefer component APIs when a repeated pattern gains meaning.'] },

  { group: 'Patterns', id: 'masthead', name: 'Masthead', description: 'Brand, global navigation, service controls, and a high-priority action in one responsive shell.', preview: `<header class="fd-masthead" style="width:100%"><a class="fd-wordmark" href="#"><span class="fd-wordmark__mark">╳</span><span>FOUNDRY UI</span></a><nav><a href="#">Products</a><a href="#">Resources</a><a href="#">Support</a></nav><button class="fd-button fd-button--primary">Get started</button></header>`, accessibility: ['Use a single site-home link.', 'Provide a mobile navigation trigger with expanded state.'] },
  { group: 'Patterns', id: 'pattern-breadcrumb', name: 'Breadcrumb', description: 'A page-level hierarchy trail with a single current destination.', preview: stack(`<nav aria-label="Breadcrumb"><ol class="fd-breadcrumbs"><li><a class="fd-link" href="#">Home</a>${icon('chevron-right')}</li><li><a class="fd-link" href="#">Workspace</a>${icon('chevron-right')}</li><li aria-current="page">Module</li></ol></nav>`), accessibility: ['Mark the final item with aria-current="page".', 'Do not include the current page as an active link.'] },
  { group: 'Patterns', id: 'inputfield-wrappers', name: 'Inputfield Wrappers', description: 'Standard wrappers for prefixes, suffixes, actions, descriptions, and validation.', preview: stack(`<label class="fd-field fd-inputfield-wrapper"><span class="fd-label">Budget</span><span class="fd-input-group"><span>€</span><input class="fd-input" value="25,000"><button class="fd-icon-button" aria-label="Clear">${icon('close')}</button></span><span class="fd-description">Enter the approved total.</span></label>`), accessibility: ['Keep the visible label associated with the inner control.', 'Name inline action buttons independently.'] },
  { group: 'Patterns', id: 'module-guidelines', name: 'Module Guidelines', description: 'A documented anatomy for reusable feature modules and their required states.', preview: `<article class="fd-module"><header><span class="fd-chip">Guideline</span><h2>Module anatomy</h2></header><ol class="fd-list fd-list--ordered"><li>Purpose and content contract</li><li>Default, loading, empty, error, and success states</li><li>Responsive and accessibility behaviour</li></ol><footer><a class="fd-link" href="#">Read implementation rules ${icon('arrow-right')}</a></footer></article>`, accessibility: ['Document keyboard, focus, and announcement behaviour with each module.', 'Define empty and error states before release.'] },
  { group: 'Patterns', id: 'module-workspace', name: 'Module Workspace', description: 'A practical canvas for composing, inspecting, and validating isolated modules.', preview: `<div class="fd-workspace"><aside><strong>Module settings</strong><label class="fd-field"><span class="fd-label">Density</span><select class="fd-select"><option>Comfortable</option><option>Compact</option></select></label></aside><section><div class="fd-workspace__canvas"><article class="fd-card"><div class="fd-card__body"><span class="fd-card__category">Preview</span><h3>Workspace module</h3><p>Inspect the module in isolation.</p></div></article></div></section></div>`, accessibility: ['Maintain logical focus order between controls and canvas.', 'Expose preview status changes through a live region when needed.'] },
  { group: 'Patterns', id: 'modal', name: 'Modal', description: 'A focused blocking task with heading, message, and ordered actions.', preview: stack(`<button class="fd-button fd-button--primary" data-demo-dialog>Open modal</button><dialog class="fd-dialog"><h2>Publish changes?</h2><p>The new configuration will become visible immediately.</p><div class="fd-dialog__actions"><button class="fd-button fd-button--secondary" data-dialog-close>Cancel</button><button class="fd-button fd-button--primary">Publish</button></div></dialog>`), accessibility: ['Trap focus while open and restore it to the trigger.', 'Use a visible heading referenced by aria-labelledby.'] },
  { group: 'Patterns', id: 'offcanvas', name: 'Offcanvas', description: 'A side sheet for navigation, filters, or supporting tasks.', preview: `<div class="fd-offcanvas-demo"><main><button class="fd-button fd-button--secondary">Open filters</button></main><aside class="fd-offcanvas" aria-label="Filters"><header><h2>Filters</h2><button class="fd-icon-button" aria-label="Close filters">${icon('close')}</button></header><label class="fd-checkbox"><input type="checkbox" checked><span class="fd-checkbox__control"></span><span>Available now</span></label><label class="fd-checkbox"><input type="checkbox"><span class="fd-checkbox__control"></span><span>Featured</span></label></aside></div>`, accessibility: ['Treat modal side sheets as dialogs and trap focus.', 'Keep non-modal offcanvas content in a predictable reading order.'] },
  { group: 'Patterns', id: 'dropdown-navbar-dd', name: 'Dropdown & Navbar DD', description: 'Action dropdown and full-width navigation dropdown patterns.', preview: `<div class="fd-dropdown-demo"><details class="fd-dropdown"><summary class="fd-button fd-button--secondary">Actions ${icon('chevron-down')}</summary><div class="fd-dropdown__menu"><button>Edit</button><button>Duplicate</button><button>Archive</button></div></details><div class="fd-navbar-dd"><div><strong>Explore</strong><a href="#">Foundations</a><a href="#">Components</a></div><div><strong>Build</strong><a href="#">Patterns</a><a href="#">Workspace</a></div></div></div>`, accessibility: ['Support Escape and arrow-key movement.', 'Return focus to the trigger after closing.'] },
  { group: 'Patterns', id: 'lightbox', name: 'Lightbox', description: 'A focused image or media viewer over a dimmed context.', preview: `<div class="fd-lightbox"><button class="fd-icon-button fd-lightbox__close" aria-label="Close preview">${icon('close')}</button><div class="fd-lightbox__media">Preview</div><p>Interface asset · 1600 × 900</p><div><button class="fd-slidenav" aria-label="Previous asset">${icon('arrow-left')}</button><button class="fd-slidenav" aria-label="Next asset">${icon('arrow-right')}</button></div></div>`, accessibility: ['Use dialog semantics and trap focus.', 'Provide text alternatives and keyboard navigation for media.'] },
  { group: 'Patterns', id: 'notifications', name: 'Notifications', description: 'A stacked notification centre for persistent and dismissible updates.', preview: `<div class="fd-notifications"><article class="fd-notification">${icon('info')}<div><strong>Workspace updated</strong><p>Changes were saved two minutes ago.</p></div><button class="fd-icon-button" aria-label="Dismiss notification">${icon('close')}</button></article><article class="fd-notification">${icon('users')}<div><strong>New collaborator</strong><p>Alex joined the module workspace.</p></div></article></div>`, accessibility: ['Announce new notifications without moving focus.', 'Persist important messages until explicitly resolved.'] },
  { group: 'Patterns', id: 'pattern-pagination', name: 'Pagination', description: 'A page navigation pattern with current, previous, and next states.', preview: stack(`<nav class="fd-pagination" aria-label="Results pages"><button aria-label="Previous page">${icon('arrow-left')}</button><button aria-current="page">1</button><button>2</button><button>3</button><button aria-label="Next page">${icon('arrow-right')}</button></nav>`), accessibility: ['Name the pagination region.', 'Mark the current page and disable unavailable directions.'] },
  { group: 'Patterns', id: 'description-list', name: 'Description List', description: 'Pairs terms and values for metadata, account details, and summaries.', preview: `<dl class="fd-description-list"><div><dt>Owner</dt><dd>Alex Morgan</dd></div><div><dt>Status</dt><dd><span class="fd-badge fd-badge--success">Active</span></dd></div><div><dt>Last updated</dt><dd>25 August 2026</dd></div></dl>`, accessibility: ['Use description lists for genuine term-value relationships.', 'Keep each term adjacent to its description.'] },
  { group: 'Patterns', id: 'pattern-search', name: 'Search', description: 'A complete search pattern with query entry, result summary, and filters.', preview: `<div class="fd-search-pattern"><form class="fd-search" role="search"><input class="fd-input" type="search" aria-label="Search documentation" value="buttons"><button class="fd-button fd-button--primary">${icon('search')} Search</button></form><p><strong>12 results</strong> for “buttons”</p><div class="fd-tag">Components <button aria-label="Remove Components filter">${icon('close')}</button></div></div>`, accessibility: ['Announce the number of results after submission.', 'Preserve the query when navigating result pages.'] },
  { group: 'Patterns', id: 'comment', name: 'Comment', description: 'A discussion item with author, timestamp, body, and contextual actions.', preview: `<article class="fd-comment"><div class="fd-comment__avatar" aria-hidden="true">AM</div><div><header><strong>Alex Morgan</strong><time datetime="2026-08-25T10:30:00Z">10:30</time></header><p>The new field wrapper should also demonstrate its error state.</p><div><button class="fd-button fd-button--tertiary fd-button--small">Reply</button><button class="fd-icon-button" aria-label="More comment actions">${icon('menu')}</button></div></div></article>`, accessibility: ['Use a time element with a machine-readable datetime.', 'Name contextual action menus with the comment context.'] },
  { group: 'Patterns', id: 'panel-scrollable', name: 'Panel & Scrollable', description: 'A bounded content panel with independent scrolling and sticky controls.', preview: `<section class="fd-panel" style="width:100%"><header><h2>Activity</h2><button class="fd-button fd-button--secondary fd-button--small">Filter</button></header><div class="fd-panel__scrollable" tabindex="0"><p><strong>10:42</strong> Module published</p><p><strong>10:31</strong> Accessibility notes updated</p><p><strong>10:12</strong> New icon added</p><p><strong>09:58</strong> Workspace created</p><p><strong>09:40</strong> Tokens imported</p></div></section>`, accessibility: ['Make keyboard-scrollable regions focusable and labelled.', 'Avoid nested scroll areas unless the boundary is visually clear.'] }
];

const updateComponent = (id, changes) => Object.assign(window.FOUNDRY_COMPONENTS.find((item) => item.id === id), changes);

